"use client";
import { useRef, useState } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);
import { useGSAP } from '@gsap/react';
import { MapPin, Phone, MessageCircle } from 'lucide-react';

export default function Contato() {
  const sectionRef = useRef<HTMLElement>(null);
  const formRef = useRef<HTMLFormElement>(null);
  const infoRef = useRef<HTMLDivElement>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useGSAP(() => {
    if (!sectionRef.current || !formRef.current || !infoRef.current) return;

    gsap.from(infoRef.current.children, {
      scrollTrigger: {
        trigger: sectionRef.current,
        start: 'top 75%',
      },
      y: 30,
      opacity: 0,
      duration: 0.8,
      stagger: 0.1,
      ease: 'power3.out',
    });

    gsap.from(formRef.current, {
      scrollTrigger: {
        trigger: sectionRef.current,
        start: 'top 75%',
      },
      x: 30,
      opacity: 0,
      duration: 1,
      ease: 'power3.out',
    });
  }, { scope: sectionRef });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    // Simulate form submission
    setTimeout(() => {
      setIsSubmitting(false);
      alert('Mensagem enviada com sucesso! Entraremos em contato em breve.');
      (e.target as HTMLFormElement).reset();
    }, 1500);
  };

  return (
    <section id="contato" ref={sectionRef} className="py-24 md:py-32 bg-bg-main relative">
      <div className="container mx-auto px-6 md:px-12">
        <div className="flex flex-col lg:flex-row gap-16 lg:gap-24">
          
          {/* Info Column */}
          <div className="w-full lg:w-5/12" ref={infoRef}>
            <span className="text-accent font-body text-sm font-bold tracking-widest uppercase mb-4 block">
              Agendamento
            </span>
            <h2 className="text-4xl md:text-5xl font-heading font-bold text-primary-dark mb-6 leading-tight">
              Vamos cuidar da <br/> sua pele juntos?
            </h2>
            <p className="text-secondary-dark/80 font-body text-lg mb-12">
              Agende sua consulta e dê o primeiro passo para uma pele saudável, cuidada com ciência, ética e respeito à sua individualidade.
            </p>

            <a 
              href="https://wa.me/5517999999999" 
              target="_blank" 
              rel="noopener noreferrer"
              className="inline-flex items-center justify-center gap-3 w-full sm:w-auto px-8 py-4 bg-[#25D366] text-white font-body font-semibold text-lg hover:bg-[#20bd5a] transition-colors mb-12 group shadow-lg shadow-[#25D366]/20"
            >
              <MessageCircle size={24} className="group-hover:scale-110 transition-transform" />
              Agendar via WhatsApp
            </a>

            <div className="space-y-8">
              <div className="flex items-start gap-4">
                <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center flex-shrink-0 shadow-sm">
                  <MapPin size={20} className="text-accent" />
                </div>
                <div>
                  <h4 className="font-heading font-semibold text-primary-dark mb-1">Localização</h4>
                  <p className="font-body text-secondary-dark/80 text-sm leading-relaxed">
                    Edifício Medical Center<br/>
                    Av. Exemplo, 1000 - Sala 101<br/>
                    São José do Rio Preto - SP
                  </p>
                </div>
              </div>
              
              <div className="flex items-start gap-4">
                <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center flex-shrink-0 shadow-sm">
                  <Phone size={20} className="text-accent" />
                </div>
                <div>
                  <h4 className="font-heading font-semibold text-primary-dark mb-1">Telefone</h4>
                  <p className="font-body text-secondary-dark/80 text-sm">
                    (17) 99999-9999
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Form Column */}
          <div className="w-full lg:w-7/12">
            <div className="bg-white p-8 md:p-12 shadow-sm border border-neutral-gray/10">
              <h3 className="text-2xl font-heading font-bold text-primary-dark mb-8">
                Envie uma mensagem
              </h3>
              
              <form ref={formRef} onSubmit={handleSubmit} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label htmlFor="name" className="font-body text-sm font-medium text-secondary-dark">Nome Completo</label>
                    <input 
                      type="text" 
                      id="name" 
                      required
                      className="w-full bg-bg-main border-none px-4 py-3 font-body text-secondary-dark focus:ring-2 focus:ring-accent outline-none transition-shadow"
                    />
                  </div>
                  <div className="space-y-2">
                    <label htmlFor="phone" className="font-body text-sm font-medium text-secondary-dark">Telefone / WhatsApp</label>
                    <input 
                      type="tel" 
                      id="phone" 
                      required
                      className="w-full bg-bg-main border-none px-4 py-3 font-body text-secondary-dark focus:ring-2 focus:ring-accent outline-none transition-shadow"
                    />
                  </div>
                </div>
                
                <div className="space-y-2">
                  <label htmlFor="email" className="font-body text-sm font-medium text-secondary-dark">E-mail</label>
                  <input 
                    type="email" 
                    id="email" 
                    required
                    className="w-full bg-bg-main border-none px-4 py-3 font-body text-secondary-dark focus:ring-2 focus:ring-accent outline-none transition-shadow"
                  />
                </div>

                <div className="space-y-2">
                  <label htmlFor="message" className="font-body text-sm font-medium text-secondary-dark">Mensagem (Opcional)</label>
                  <textarea 
                    id="message" 
                    rows={4}
                    className="w-full bg-bg-main border-none px-4 py-3 font-body text-secondary-dark focus:ring-2 focus:ring-accent outline-none transition-shadow resize-none"
                  ></textarea>
                </div>

                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="w-full group relative px-8 py-4 overflow-hidden bg-primary-dark text-white font-body font-medium transition-all text-center disabled:opacity-70 disabled:cursor-not-allowed mt-4"
                >
                  <span className="relative z-10 tracking-wide">
                    {isSubmitting ? 'Enviando...' : 'Enviar Mensagem'}
                  </span>
                  {!isSubmitting && (
                    <div className="absolute inset-0 bg-accent translate-y-[100%] group-hover:translate-y-0 transition-transform duration-300 ease-out z-0"></div>
                  )}
                </button>
                <p className="font-body text-xs text-neutral-gray/80 text-center mt-4">
                  Seus dados estão seguros e não serão compartilhados com terceiros.
                </p>
              </form>
            </div>
          </div>

        </div>
      </div>
    </section>
  );
}
